/// A place's two markers: the one the World Map draws, and the one the map
/// screen draws.
#define PLACE_MARKERS(marker, mapMarker) ((marker) | (mapMarker) << 4)

/// No scene marks the place visited.
#define PLACE_NEVER_VISITED -1, -2

